(5468257, 787611, 33352, '<td valign="top">interesting processing to shut out the sun and still have it for lighting...</td>', 'interesting processing to shut out the sun and still have it for lighting...', '2009-05-04 17:52:58.000000', NULL, 1),
(5468259, 787910, 26001, '<td valign="top">colors are simply gorgeous. considering all these shining stuff, you have done a nice job lighting the setup.</td>', 'colors are simply gorgeous. considering all these shining stuff, you have done a nice job lighting the setup.', '2009-05-04 17:53:30.000000', NULL, 1),
(5468260, 787708, 33352, '<td valign="top">The camera does not appear to be on the same table, good focus...</td>', 'The camera does not appear to be on the same table, good focus...', '2009-05-04 17:54:07.000000', NULL, 1),
(5468261, 787657, 33352, '<td valign="top">nice composition, a little dark IMHO...</td>', 'nice composition, a little dark IMHO...', '2009-05-04 17:55:12.000000', NULL, 1),
(5468262, 787690, 33352, '<td valign="top">Like mine cooked more, clever idea...</td>', 'Like mine cooked more, clever idea...', '2009-05-04 17:56:24.000000', NULL, 1),
(5468266, 787896, 33352, '<td valign="top">A little busy, and the red draws you away from the subject...</td>', 'A little busy, and the red draws you away from the subject...', '2009-05-04 17:57:39.000000', NULL, 1),
(5468268, 787455, 101256, '<td valign="top">There are two ways to look at this image - one, it has a lot of blank space which could be viewed as a negative. Or one could view the rather large space as a positive controlling the core subject by bringing the eye to the object instead of away from it. In either case, this works fine as it is, although the offset to the left could be a little less strong to eliminate the sense of space while keeping the same image size. The image is technically successful without any significant issues - properly focused showing rich detail complimented by the reflection on the surface. As a stand alone art print, it also works as the soft reflected light addresses the need for depth and dimension. Well done - this would work very well as a photo-on-canvass print.</td>', 'There are two ways to look at this image - one, it has a lot of blank space which could be viewed as a negative. Or one could view the rather large space as a positive controlling the core subject by bringing the eye to the object instead of away from it. In either case, this works fine as it is, although the offset to the left could be a little less strong to eliminate the sense of space while keeping the same image size. The image is technically successful without any significant issues - properly focused showing rich detail complimented by the reflection on the surface. As a stand alone art print, it also works as the soft reflected light addresses the need for depth and dimension. Well done - this would work very well as a photo-on-canvass print.', '2009-05-04 17:58:37.000000', NULL, 1),
(5468269, 787831, 33352, '<td valign="top">nice image a shallower DOF would have been better IMHO, without loosing the story,</td>', 'nice image a shallower DOF would have been better IMHO, without loosing the story,', '2009-05-04 17:59:28.000000', NULL, 1),
(5468271, 787416, 33352, '<td valign="top">Like this as the composition fits the title...</td>', 'Like this as the composition fits the title...', '2009-05-04 18:00:25.000000', NULL, 1),
