(5468381, 787239, 101256, '<td valign="top">A moment frozen in time. Technically competant, the lack of motion leaves a static impression that, while not negative, isn''t positive either - it would help to have some movement to express the idea - this image gives an impression of being a "trick" image rather than a natural physical action/reaction. A good solid entry into the challenge.</td>', 'A moment frozen in time. Technically competant, the lack of motion leaves a static impression that, while not negative, isn''t positive either - it would help to have some movement to express the idea - this image gives an impression of being a "trick" image rather than a natural physical action/reaction. A good solid entry into the challenge.', '2009-05-04 18:47:52.000000', NULL, 1),
(5468438, 787719, 33352, '<td valign="top">Table top is meant to be taken with the camera on the table with the subject to create a different perspective...</td>', 'Table top is meant to be taken with the camera on the table with the subject to create a different perspective...', '2009-05-04 19:28:13.000000', NULL, 1),
