(5469435, 787663, 99708, '<td valign="top">I love this one!</td>', 'I love this one!', '2009-05-05 01:38:00.000000', NULL, 1),
(5469438, 787666, 99708, '<td valign="top">This is a wonderful shot, and would of scored it higher if the comcast remote was not in it.</td>', 'This is a wonderful shot, and would of scored it higher if the comcast remote was not in it.', '2009-05-05 01:39:19.000000', NULL, 1),
(5469440, 787657, 99708, '<td valign="top">Beautiful.  (enough said)</td>', 'Beautiful.  (enough said)', '2009-05-05 01:40:04.000000', NULL, 1),
(5469581, 787167, 96751, '<td valign="top">Nice tonal qualities, but I find the composition a bit linear.</td>', 'Nice tonal qualities, but I find the composition a bit linear.', '2009-05-05 04:01:27.000000', NULL, 1),
(5469582, 787582, 96751, '<td valign="top">Nice motion shot.</td>', 'Nice motion shot.', '2009-05-05 04:01:50.000000', NULL, 1),
(5469586, 787933, 96751, '<td valign="top">Definitely a table top shot, although it is lacking dynamics in lighting, tones, and colors.  The main subject, the lemon, is lacking in detail</td>', 'Definitely a table top shot, although it is lacking dynamics in lighting, tones, and colors.  The main subject, the lemon, is lacking in detail', '2009-05-05 04:03:53.000000', NULL, 1),
(5469587, 787613, 96751, '<td valign="top">Nice bokeh and clarity in the beer.  Great dof.</td>', 'Nice bokeh and clarity in the beer.  Great dof.', '2009-05-05 04:04:14.000000', NULL, 1),
(5469590, 787888, 96751, '<td valign="top">Looks like it was a fun party!</td>', 'Looks like it was a fun party!', '2009-05-05 04:04:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5469592, 786156, 96751, '<td valign="top">Very creative idea.  Great execution, nice and shart foreground, great motion blur.</td>', 'Very creative idea.  Great execution, nice and shart foreground, great motion blur.', '2009-05-05 04:05:27.000000', NULL, 1),
(5469594, 787349, 96751, '<td valign="top">Very clever.  Love the monotone.  Maybe just a little less table to make his eyes a bit more prominent.</td>', 'Very clever.  Love the monotone.  Maybe just a little less table to make his eyes a bit more prominent.', '2009-05-05 04:06:00.000000', NULL, 1),
(5469597, 787881, 96751, '<td valign="top">Incredible detail in this model (?).  Wonderful lighting.  Perhaps less back lighting on the flag so that the symbol is clearer.</td>', 'Incredible detail in this model (?).  Wonderful lighting.  Perhaps less back lighting on the flag so that the symbol is clearer.', '2009-05-05 04:06:55.000000', NULL, 1),
(5469598, 787882, 96751, '<td valign="top">Great pov.</td>', 'Great pov.', '2009-05-05 04:07:20.000000', NULL, 1),
(5469600, 787683, 96751, '<td valign="top">There is something oddly pleasing about this shot.  Great clors, nice bokeh reflected on the surface.  Maybe a bit of zest curls for added texture?</td>', 'There is something oddly pleasing about this shot.  Great clors, nice bokeh reflected on the surface.  Maybe a bit of zest curls for added texture?', '2009-05-05 04:08:16.000000', NULL, 1),
(5469602, 787908, 96751, '<td valign="top">Definitely table top, but needs a bit more back lighting on the beer.</td>', 'Definitely table top, but needs a bit more back lighting on the beer.', '2009-05-05 04:08:58.000000', NULL, 1),
(5469603, 787239, 96751, '<td valign="top">Wonderful timing.  Really fabulous.  I wish you had used a  more even backdrop and adjusted the lighting so it wouldn''t be so glarey on the surface of the tiles.</td>', 'Wonderful timing.  Really fabulous.  I wish you had used a  more even backdrop and adjusted the lighting so it wouldn''t be so glarey on the surface of the tiles.', '2009-05-05 04:10:18.000000', NULL, 1),
(5469604, 787837, 96751, '<td valign="top">Great mood shot.  Very mysterious.  The wood grain really is an illuminated path.</td>', 'Great mood shot.  Very mysterious.  The wood grain really is an illuminated path.', '2009-05-05 04:11:09.000000', NULL, 1),
(5469605, 787883, 96751, '<td valign="top">Absolutely prosh.</td>', 'Absolutely prosh.', '2009-05-05 04:11:28.000000', NULL, 1),
(5469606, 787060, 96751, '<td valign="top">Nice symmetry shot.</td>', 'Nice symmetry shot.', '2009-05-05 04:11:37.000000', NULL, 1),
(5469607, 787200, 96751, '<td valign="top">Great imagination.  I knew right away what they were, yet lingered to take in this unusual perspective.  I think the focus might be slightly off on the tips of the tines, of that the dof is just too shallow.</td>', 'Great imagination.  I knew right away what they were, yet lingered to take in this unusual perspective.  I think the focus might be slightly off on the tips of the tines, of that the dof is just too shallow.', '2009-05-05 04:12:47.000000', NULL, 1),
(5469609, 787663, 96751, '<td valign="top">There is so much going on in this shot.  Very interesting.  From the two in the front to the teacher in the back - great image.</td>', 'There is so much going on in this shot.  Very interesting.  From the two in the front to the teacher in the back - great image.', '2009-05-05 04:13:27.000000', NULL, 1),
