(5469636, 787168, 96751, '<td valign="top">The color seems to be a bit off, into the pink realm.  The critter is adorable, but seems just a tad out of focus</td>', 'The color seems to be a bit off, into the pink realm.  The critter is adorable, but seems just a tad out of focus', '2009-05-05 04:28:53.000000', NULL, 1),
(5469637, 787901, 96751, '<td valign="top">Great chessboard.  Dramatic lighting.</td>', 'Great chessboard.  Dramatic lighting.', '2009-05-05 04:29:19.000000', NULL, 1),
