(5480584, 787011, 87808, '<td valign="top">Ouch, sorry for the DQ.  Amazingly brilliant simple shot though that deserved its placement.</td>', 'Ouch, sorry for the DQ.  Amazingly brilliant simple shot though that deserved its placement.', '2009-05-11 12:16:36.000000', NULL, 0),
(5480601, 786585, 95579, '<td valign="top">I think im doing something wrong with my iphone - or maybe you just have a whole load of talent! (im going for the latter). Congrats<br/> <br/>Really fab image, specially when considering your "camera". The smoothness adds a slight surreal tone to the image, its really fantastic.  Im taking more shots with my iphone!! if I could work out how to get them off it of course..</td>', 'I think im doing something wrong with my iphone - or maybe you just have a whole load of talent! (im going for the latter). Congrats Really fab image, specially when considering your "camera". The smoothness adds a slight surreal tone to the image, its really fantastic.  Im taking more shots with my iphone!! if I could work out how to get them off it of course..', '2009-05-11 12:24:15.000000', NULL, 0),
(5480603, 787846, 95579, '<td valign="top">Congrts on top 10. Love the humour</td>', 'Congrts on top 10. Love the humour', '2009-05-11 12:25:45.000000', NULL, 0),
