INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5480690, 787663, 67237, '<td valign="top">Huge congrats on this well deserved ribbon Michelle. You have a great b&amp;w sense.</td>', 'Huge congrats on this well deserved ribbon Michelle. You have a great b&w sense.', '2009-05-11 13:45:08.000000', NULL, 0),
(5480693, 787011, 53964, '<td valign="top">Aww, that''s a shame :(    Still a great shot though. Nothing can take that away :)</td>', 'Aww, that''s a shame :(    Still a great shot though. Nothing can take that away :)', '2009-05-11 13:48:44.000000', NULL, 0),
(5480697, 786585, 67237, '<td valign="top">Huge congrats Paul!!!<br/>It''s amazing how you post processed and squeezed the Iphone to the limit. BTW is it a 3G iphone :) ?</td>', 'Huge congrats Paul!!!It''s amazing how you post processed and squeezed the Iphone to the limit. BTW is it a 3G iphone :) ?', '2009-05-11 13:51:36.000000', NULL, 0),
(5480699, 787837, 67237, '<td valign="top">huge congrats on the ribbon Darren!!!</td>', 'huge congrats on the ribbon Darren!!!', '2009-05-11 13:53:43.000000', NULL, 0),
(5480712, 787663, 66384, '<td valign="top">Michelle, this is so awesome! Imagine a candid winning a blue ribbon and a 7+ score. Congratulations!!</td>', 'Michelle, this is so awesome! Imagine a candid winning a blue ribbon and a 7+ score. Congratulations!!', '2009-05-11 14:10:12.000000', NULL, 0),
(5480715, 787663, 24454, '<td valign="top">Michelle!  CONGRATULATIONS!  What a fabulous photo for this challenge.  I feel like I''m looking into another era.  And the boy in the suit.  He makes my heart hurt! :)<br/> <br/>Way to GO!</td>', 'Michelle!  CONGRATULATIONS!  What a fabulous photo for this challenge.  I feel like I''m looking into another era.  And the boy in the suit.  He makes my heart hurt! :) Way to GO!', '2009-05-11 14:11:22.000000', NULL, 0),
(5480716, 787011, 67697, '<td valign="top">Oh that is too bad :(  Sorry to see about the DQ.  Still a great shot tho!</td>', 'Oh that is too bad :(  Sorry to see about the DQ.  Still a great shot tho!', '2009-05-11 14:11:49.000000', NULL, 0),
(5480717, 787837, 67697, '<td valign="top">Congrats on your ribbon!  So where was this taken?</td>', 'Congrats on your ribbon!  So where was this taken?', '2009-05-11 14:12:27.000000', NULL, 0),
(5480719, 786585, 24454, '<td valign="top">Oh, way to go!  An iphone!!  You are the BOMB!  And I can''t imagine anything any more beautiful taken with a high dollar camera.  CONGRATULATIONS!   With so much high-tech camera equipment out there -- it is so refreshing to have it confirmed that you don''t HAVE to have the most expensive, latest and greatest of everything to take great photos!<br/> <br/></td>', 'Oh, way to go!  An iphone!!  You are the BOMB!  And I can''t imagine anything any more beautiful taken with a high dollar camera.  CONGRATULATIONS!   With so much high-tech camera equipment out there -- it is so refreshing to have it confirmed that you don''t HAVE to have the most expensive, latest and greatest of everything to take great photos! ', '2009-05-11 14:13:37.000000', NULL, 0),
(5480724, 787593, 56502, '<td valign="top">I think it''s a nice shot (I agree with the other commenter regarding the contrast, though) and don''t mind the crop, it makes it more interesting in my eyes.<br/>However, there is nothing <b>in the picture</b> that conveys the idea of table shot, even if it was done that way. The shot would have been exactly the same if you had used a tripod. I didn''t vote nor take part in the challenge, but I would have missed that element as well.</td>', 'I think it''s a nice shot (I agree with the other commenter regarding the contrast, though) and don''t mind the crop, it makes it more interesting in my eyes.However, there is nothing in the picture that conveys the idea of table shot, even if it was done that way. The shot would have been exactly the same if you had used a tripod. I didn''t vote nor take part in the challenge, but I would have missed that element as well.', '2009-05-11 14:19:36.000000', NULL, 0),
(5480727, 787011, 3214, '<td valign="top">So sorry about the DQ, terrific, innovative response to the theme.</td>', 'So sorry about the DQ, terrific, innovative response to the theme.', '2009-05-11 14:23:32.000000', NULL, 0),
(5480728, 786585, 81530, '<td valign="top">First iPhone photo to win a ribbon. Congrats.</td>', 'First iPhone photo to win a ribbon. Congrats.', '2009-05-11 14:23:46.000000', NULL, 0),
(5480733, 787810, 67697, '<td valign="top">Great emotive shot.  What an interesting story to go with the photo.  Glad to see you and Aimee submitting again :)</td>', 'Great emotive shot.  What an interesting story to go with the photo.  Glad to see you and Aimee submitting again :)', '2009-05-11 14:32:28.000000', NULL, 0),
(5480736, 787011, 52549, '<td valign="top">Sorry about the DQ, It''s a wonderful image.</td>', 'Sorry about the DQ, It''s a wonderful image.', '2009-05-11 14:34:52.000000', NULL, 0),
(5480739, 787837, 52549, '<td valign="top">Darren, you do such wonderful work. In fact, you''re one of my favourite photographers here at dpc. Many congrats on the ribbon.</td>', 'Darren, you do such wonderful work. In fact, you''re one of my favourite photographers here at dpc. Many congrats on the ribbon.', '2009-05-11 14:36:32.000000', NULL, 0),
(5480741, 787915, 52549, '<td valign="top">You certainly should be happy with this, it''s fantastic. Love the lighting too.</td>', 'You certainly should be happy with this, it''s fantastic. Love the lighting too.', '2009-05-11 14:38:11.000000', NULL, 0),
(5480802, 786585, 30861, '<td valign="top">I was gonna do a mild slammin'' on the excessive noise reduction aspect of this, until I read your notes :-) An iPhone, eh? No KIDDING? This is a milestone! And you know, the thing of it is, the hyper-smooth mien of the finished image is actually oddly appealing, if not entirely my cup of tea. So congrats! Well done!</td>', 'I was gonna do a mild slammin'' on the excessive noise reduction aspect of this, until I read your notes :-) An iPhone, eh? No KIDDING? This is a milestone! And you know, the thing of it is, the hyper-smooth mien of the finished image is actually oddly appealing, if not entirely my cup of tea. So congrats! Well done!', '2009-05-11 15:10:17.000000', NULL, 0),
(5480804, 787663, 30861, '<td valign="top">This is absolutely an exceptional image. I''m SO Pleased to see this intensely *real* little slice-of-life bag the blue in what turned out to be an extremely *artificial* challenge, by and large. What I mean by that is that most of the images seemed rater forced (my own not excepted), and this one stands out as being completely natural. So big congrats!</td>', 'This is absolutely an exceptional image. I''m SO Pleased to see this intensely *real* little slice-of-life bag the blue in what turned out to be an extremely *artificial* challenge, by and large. What I mean by that is that most of the images seemed rater forced (my own not excepted), and this one stands out as being completely natural. So big congrats!', '2009-05-11 15:12:37.000000', NULL, 0),
(5480807, 787732, 22538, '<td valign="top">Congratulations, well thought and very stylish.</td>', 'Congratulations, well thought and very stylish.', '2009-05-11 15:19:24.000000', NULL, 0),
(5480883, 787841, 28322, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by michaelmonn:</b></div><hr/><i> im quite upset that this didnt do much better. it was the only image in the entire challenge i gave a 10 because it just has so much personality. excellent shot. </i></td></tr></table> <br/> <br/>Thanks Max, I really appreciate your kind words, <br/>All the best, Cheers,</td>', 'Originally posted by michaelmonn: im quite upset that this didnt do much better. it was the only image in the entire challenge i gave a 10 because it just has so much personality. excellent shot.   Thanks Max, I really appreciate your kind words, All the best, Cheers,', '2009-05-11 16:01:59.000000', NULL, 0),
(5480889, 787841, 30982, '<td valign="top">This is adorable!  Clever idea, well executed!  On my screen it looks as though it could use just a touch of sharpening.  Can''t see where you had that in your steps.  Try resizing aftter you''ve finished processing to twice the size you want to end up with (ie 1440 pixels wide if you want 720 pixels as your finished size) and "Sharpen" once - then maybe once more if it needs it.  THEN resize to 720 pixels.</td>', 'This is adorable!  Clever idea, well executed!  On my screen it looks as though it could use just a touch of sharpening.  Can''t see where you had that in your steps.  Try resizing aftter you''ve finished processing to twice the size you want to end up with (ie 1440 pixels wide if you want 720 pixels as your finished size) and "Sharpen" once - then maybe once more if it needs it.  THEN resize to 720 pixels.', '2009-05-11 16:09:50.000000', NULL, 0),
(5480927, 787663, 62318, '<td valign="top">Woot!</td>', 'Woot!', '2009-05-11 16:39:08.000000', NULL, 0),
